import{_ as a,o as n,c as s,a3 as e}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"框架选型与 ADR","description":"比较 TS-AI 全栈中前端、后端与 Agent/工作流候选，给出后果与复查条件，并提供可粘贴的 ADR 写法示例。","frontmatter":{"title":"框架选型与 ADR","description":"比较 TS-AI 全栈中前端、后端与 Agent/工作流候选，给出后果与复查条件，并提供可粘贴的 ADR 写法示例。","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"ts-ai/architecture/design-decisions/framework-selection-adr.md","filePath":"ts-ai/architecture/design-decisions/framework-selection-adr.md","lastUpdated":1786166505000}'),r={name:"ts-ai/architecture/design-decisions/framework-selection-adr.md"};function d(l,t,p,i,o,h){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="框架选型与-adr" tabindex="-1">框架选型与 ADR <a class="header-anchor" href="#框架选型与-adr" aria-label="Permalink to &quot;框架选型与 ADR&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>「我们用 Nuxt + Nest + LangChain + LangGraph」常常是结果，不是论证。本篇示范如何把全栈 AI 选型写成<strong>可复查的 ADR</strong>：先拆层，再比候选，再写后果与触发重评的条件。场景固定为 TypeScript 售后或知识库全栈；不展开各框架 API。</p><p>相关：<a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a>、<a href="/ts-ai/architecture/design-decisions/model-gateway">模型网关</a>、<a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent / Chain / Workflow 边界</a>。Python 侧对照可读 py-agent 的框架选型文，但本篇以 TS 约束为准。</p><h2 id="_1-背景" tabindex="-1">1. 背景 <a class="header-anchor" href="#_1-背景" aria-label="Permalink to &quot;1. 背景&quot;">​</a></h2><h3 id="_1-1-为什么选型会失败" tabindex="-1">1.1 为什么选型会失败 <a class="header-anchor" href="#_1-1-为什么选型会失败" aria-label="Permalink to &quot;1.1 为什么选型会失败&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失败模式</th><th>表现</th></tr></thead><tbody><tr><td>品牌打包</td><td>四个框架绑成不可拆契约，无法单层替换</td></tr><tr><td>功能清单赛</td><td>比「谁列表更长」，不比抽象是否匹配问题</td></tr><tr><td>无复查条件</td><td>一年后流量与合规变了仍不敢动</td></tr><tr><td>ADR 空心</td><td>只有结论句，没有否决项与证据</td></tr></tbody></table><h3 id="_1-2-本篇决策范围" tabindex="-1">1.2 本篇决策范围 <a class="header-anchor" href="#_1-2-本篇决策范围" aria-label="Permalink to &quot;1.2 本篇决策范围&quot;">​</a></h3><p>一次写清三层选型（可拆成多份 ADR，但论据要互相引用）：</p><ol><li><strong>交互/BFF 前端</strong>：Nuxt（Vue）为主候选</li><li><strong>应用后端</strong>：NestJS</li><li><strong>编排</strong>：LangChain.js（组件 + Agent）与按需 LangGraph.js（持久工作流）</li></ol><p>模型供应商本身另案；本篇只要求经 Gateway 交付。</p><h2 id="_2-约束与决策标准" tabindex="-1">2. 约束与决策标准 <a class="header-anchor" href="#_2-约束与决策标准" aria-label="Permalink to &quot;2. 约束与决策标准&quot;">​</a></h2><h3 id="_2-1-硬约束-示例-售后执行" tabindex="-1">2.1 硬约束（示例：售后执行） <a class="header-anchor" href="#_2-1-硬约束-示例-售后执行" aria-label="Permalink to &quot;2.1 硬约束（示例：售后执行）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>约束</th><th>取值</th></tr></thead><tbody><tr><td>语言</td><td>TypeScript 为主（前后端同语族）</td></tr><tr><td>交互</td><td>Web Chat + 审批面板；需要 SSE 或等价推流</td></tr><tr><td>后端</td><td>自托管；可接 Postgres</td></tr><tr><td>编排</td><td>短问答 Agent + <strong>可中断退款审批</strong></td></tr><tr><td>安全</td><td>密钥与 ACL 在服务端；租户隔离</td></tr><tr><td>团队</td><td>已有 Vue/Nest 经验（若你的团队不同，重填本节）</td></tr></tbody></table><p>知识库路径把「可中断退款」换成「权限检索 + 引用」；编排上可能弱化 LangGraph。</p><h3 id="_2-2-决策标准" tabindex="-1">2.2 决策标准 <a class="header-anchor" href="#_2-2-决策标准" aria-label="Permalink to &quot;2.2 决策标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标准</th><th>权重</th><th style="text-align:right;">说明</th></tr></thead><tbody><tr><td>抽象匹配</td><td>25</td><td style="text-align:right;">UI / HTTP 用例 / Agent / 持久图是否各得其所</td></tr><tr><td>状态与恢复</td><td>20</td><td style="text-align:right;">Interrupt、Checkpoint、Run 取消</td></tr><tr><td>协议可控</td><td>15</td><td style="text-align:right;">产品事件不被框架私有协议锁死</td></tr><tr><td>可测试与观测</td><td>15</td><td style="text-align:right;">Fake 模型、Trace、契约测试</td></tr><tr><td>团队学习成本</td><td>10</td><td style="text-align:right;">90 天内可交付工作台</td></tr><tr><td>退出与升级</td><td>15</td><td style="text-align:right;">单层可替换、版本迁移路径</td></tr></tbody></table><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-前端候选" tabindex="-1">3.1 前端候选 <a class="header-anchor" href="#_3-1-前端候选" aria-label="Permalink to &quot;3.1 前端候选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>候选</th><th>要点</th></tr></thead><tbody><tr><td><strong>F1 Nuxt 3 + Vue 3</strong></td><td>手册默认；composables 管 Chat 状态机；server 可作薄 BFF</td></tr><tr><td><strong>F2 Next.js + React</strong></td><td>同属全栈 TS；生态不同；协议仍应经 Nest</td></tr><tr><td><strong>F3 纯 CSR SPA（Vite + Vue）</strong></td><td>更简单部署；缺约定式 server 代理时要自建</td></tr></tbody></table><h3 id="_3-2-后端候选" tabindex="-1">3.2 后端候选 <a class="header-anchor" href="#_3-2-后端候选" aria-label="Permalink to &quot;3.2 后端候选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>候选</th><th>要点</th></tr></thead><tbody><tr><td><strong>B1 NestJS</strong></td><td>模块、DI、Guard、与手册 backend 一致</td></tr><tr><td><strong>B2 轻量 Fastify/Hono 自组装</strong></td><td>少魔法；要自建模块边界与等价能力</td></tr><tr><td><strong>B3 Serverless 函数拼装</strong></td><td>弹性好；长 SSE / 图 resume 更别扭</td></tr></tbody></table><h3 id="_3-3-编排候选" tabindex="-1">3.3 编排候选 <a class="header-anchor" href="#_3-3-编排候选" aria-label="Permalink to &quot;3.3 编排候选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>候选</th><th>要点</th></tr></thead><tbody><tr><td><strong>O1 仅供应商 SDK</strong></td><td>透明；复杂 Agent/图成本高</td></tr><tr><td><strong>O2 LangChain.js only</strong></td><td>强于组件与 <code>createAgent</code>；持久 HITL 吃力</td></tr><tr><td><strong>O3 LangChain.js + LangGraph.js</strong></td><td>手册默认售后审批组合</td></tr><tr><td><strong>O4 托管 Agent 平台</strong></td><td>省运维；数据/退出/协议受平台约束</td></tr></tbody></table><h2 id="_4-对比" tabindex="-1">4. 对比 <a class="header-anchor" href="#_4-对比" aria-label="Permalink to &quot;4. 对比&quot;">​</a></h2><h3 id="_4-1-填写完成的评分-售后执行" tabindex="-1">4.1 填写完成的评分（售后执行） <a class="header-anchor" href="#_4-1-填写完成的评分-售后执行" aria-label="Permalink to &quot;4.1 填写完成的评分（售后执行）&quot;">​</a></h3><p>评分 <code>1–5</code>，仅对「TS 售后含审批、自托管、团队会 Vue/Nest」有效。</p><p><strong>前端</strong></p><table tabindex="0"><thead><tr><th>标准</th><th>F1 Nuxt</th><th>F2 Next</th><th>F3 Vite SPA</th></tr></thead><tbody><tr><td>抽象匹配</td><td>5</td><td>5</td><td>4</td></tr><tr><td>与手册/示例对齐</td><td>5</td><td>3</td><td>3</td></tr><tr><td>BFF 便利</td><td>5</td><td>5</td><td>2</td></tr><tr><td>学习（本团队）</td><td>5</td><td>3</td><td>4</td></tr><tr><td>加权印象</td><td><strong>首选</strong></td><td>可替换方案</td><td>小型内部工具</td></tr></tbody></table><p><strong>后端</strong></p><table tabindex="0"><thead><tr><th>标准</th><th>B1 Nest</th><th>B2 轻量</th><th>B3 Serverless</th></tr></thead><tbody><tr><td>用例与 DI</td><td>5</td><td>3</td><td>2</td></tr><tr><td>长连接 / Worker 共存</td><td>5</td><td>4</td><td>2</td></tr><tr><td>测试与模块边界</td><td>5</td><td>3</td><td>2</td></tr><tr><td>加权印象</td><td><strong>首选</strong></td><td>专家团队可选</td><td>不适合审批图</td></tr></tbody></table><p><strong>编排</strong></p><table tabindex="0"><thead><tr><th>标准</th><th>O1 SDK</th><th>O2 LC only</th><th>O3 LC+LG</th><th>O4 托管</th></tr></thead><tbody><tr><td>短问答 Agent</td><td>3</td><td>5</td><td>5</td><td>4</td></tr><tr><td>Interrupt/恢复</td><td>1</td><td>2</td><td>5</td><td>4</td></tr><tr><td>协议可控</td><td>5</td><td>4</td><td>4</td><td>2</td></tr><tr><td>退出</td><td>5</td><td>3</td><td>3</td><td>1</td></tr><tr><td>加权印象</td><td>仅简单工具</td><td>知识库常够用</td><td><strong>售后首选</strong></td><td>合规允许时</td></tr></tbody></table><h3 id="_4-2-知识库路径的差异" tabindex="-1">4.2 知识库路径的差异 <a class="header-anchor" href="#_4-2-知识库路径的差异" aria-label="Permalink to &quot;4.2 知识库路径的差异&quot;">​</a></h3><p>若主路径是企业知识库而非审批图：</p><ul><li>编排可选 <strong>O2</strong>，LangGraph 列为「索引 DAG 可选」，不强制。</li><li>前端/后端结论可不变。</li><li>在 ADR 中单独写：「引入 LG 的触发条件 = 出现跨天人工审核或复杂索引状态机」。</li></ul><h2 id="_5-决策" tabindex="-1">5. 决策 <a class="header-anchor" href="#_5-决策" aria-label="Permalink to &quot;5. 决策&quot;">​</a></h2><h3 id="_5-1-默认组合-手册主路径" tabindex="-1">5.1 默认组合（手册主路径） <a class="header-anchor" href="#_5-1-默认组合-手册主路径" aria-label="Permalink to &quot;5.1 默认组合（手册主路径）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>选择</th><th>一句话理由</th></tr></thead><tbody><tr><td>前端</td><td><strong>F1 Nuxt</strong></td><td>与集成篇章一致；Chat 状态机清晰</td></tr><tr><td>后端</td><td><strong>B1 NestJS</strong></td><td>用例、鉴权、SSE、DI 与 Gateway 宿主</td></tr><tr><td>编排</td><td><strong>O3 LangChain + 按需 LangGraph</strong></td><td>Agent 覆盖对话；图覆盖退款审批</td></tr><tr><td>模型交付</td><td>Nest <strong>Model Gateway</strong></td><td>见网关 ADR</td></tr></tbody></table><p>依赖方向遵循 <a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a>：Nuxt → Nest →（LC / LG）。</p><h3 id="_5-2-明确否决-本场景" tabindex="-1">5.2 明确否决（本场景） <a class="header-anchor" href="#_5-2-明确否决-本场景" aria-label="Permalink to &quot;5.2 明确否决（本场景）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>否决</th><th>原因</th></tr></thead><tbody><tr><td>浏览器直连模型 + 无 Nest</td><td>破密钥与 ACL 硬约束</td></tr><tr><td>以托管平台为唯一编排且无适配层</td><td>产品事件与退出风险不可接受（当前约束）</td></tr><tr><td>工作台阶段上多 Agent Supervisor 网</td><td>抽象过重；违背「最简单层」</td></tr></tbody></table><h2 id="_6-后果与适用边界" tabindex="-1">6. 后果与适用边界 <a class="header-anchor" href="#_6-后果与适用边界" aria-label="Permalink to &quot;6. 后果与适用边界&quot;">​</a></h2><h3 id="_6-1-正面后果" tabindex="-1">6.1 正面后果 <a class="header-anchor" href="#_6-1-正面后果" aria-label="Permalink to &quot;6.1 正面后果&quot;">​</a></h3><ul><li>学习路径与仓库模板一致，交付「流式工作台 → 售后或知识库」可验收。</li><li>单层替换有讨论起点（例如前端换 Next，只要协议不变）。</li><li>审批恢复与 Run 取消有明确承载框架。</li></ul><h3 id="_6-2-负面后果与缓解" tabindex="-1">6.2 负面后果与缓解 <a class="header-anchor" href="#_6-2-负面后果与缓解" aria-label="Permalink to &quot;6.2 负面后果与缓解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后果</th><th>缓解</th></tr></thead><tbody><tr><td>框架升级可能改事件名/序列化</td><td>产品事件适配层；契约测试</td></tr><tr><td>团队需同时懂 Nest 与图模型</td><td>工作台先 LC；审批再开 LG 专题</td></tr><tr><td>同语族不等于零成本共享类型</td><td>用 <code>contracts/</code> / OpenAPI，不共享 Vue 组件到 Nest</td></tr></tbody></table><h3 id="_6-3-适用边界" tabindex="-1">6.3 适用边界 <a class="header-anchor" href="#_6-3-适用边界" aria-label="Permalink to &quot;6.3 适用边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>适用</th><th>需重开 ADR</th></tr></thead><tbody><tr><td>中小型自托管 TS-AI 产品</td><td>必须多语言后端</td></tr><tr><td>Chat + 工具 + 少量 HITL 图</td><td>强依赖某云 AI 控制面合规</td></tr><tr><td>手册项目实战路径</td><td>前端团队纯 React 且拒绝 Vue</td></tr></tbody></table><h2 id="_7-复查条件" tabindex="-1">7. 复查条件 <a class="header-anchor" href="#_7-复查条件" aria-label="Permalink to &quot;7. 复查条件&quot;">​</a></h2><p>任一触发则复评对应层（不必推翻全部）：</p><ol><li><strong>前端</strong>：交互团队转为 React 为主，或必须吃透某 React AI SDK 生态。</li><li><strong>后端</strong>：SSE/Worker 模型与平台限制冲突，或组织强制 Serverless-only。</li><li><strong>编排</strong>：审批复杂度证明 LG 过重（改成外部 BPM）或 O2 已不够（恢复/分支爆炸）。</li><li><strong>整体</strong>：合规禁止自托管 Checkpoint，或数据必须出域到托管平台。</li><li><strong>成本</strong>：框架升级连续两个季度占用 &gt;30% 迭代仍无业务收益。</li></ol><p>复查产出：更新评分表、新旧否决项、迁移成本估计——不是只改「状态: Accepted」日期。</p><h2 id="_8-adr-写法示例" tabindex="-1">8. ADR 写法示例 <a class="header-anchor" href="#_8-adr-写法示例" aria-label="Permalink to &quot;8. ADR 写法示例&quot;">​</a></h2><h3 id="_8-1-推荐结构" tabindex="-1">8.1 推荐结构 <a class="header-anchor" href="#_8-1-推荐结构" aria-label="Permalink to &quot;8.1 推荐结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题 / 状态 / 日期 / 场景</span></span>
<span class="line"><span>问题（一句话）</span></span>
<span class="line"><span>硬约束</span></span>
<span class="line"><span>决策标准与权重</span></span>
<span class="line"><span>候选（含未入围）</span></span>
<span class="line"><span>证据（PoC 做了什么，不是官网口号）</span></span>
<span class="line"><span>决策与否决</span></span>
<span class="line"><span>后果（正/负）与缓解</span></span>
<span class="line"><span>复查条件</span></span>
<span class="line"><span>关联 ADR / 文档链接</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="_8-2-填写完成-售后全栈选型" tabindex="-1">8.2 填写完成：售后全栈选型 <a class="header-anchor" href="#_8-2-填写完成-售后全栈选型" aria-label="Permalink to &quot;8.2 填写完成：售后全栈选型&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题：TS 售后全栈采用 Nuxt + Nest + LangChain.js + LangGraph.js</span></span>
<span class="line"><span>状态：Accepted</span></span>
<span class="line"><span>日期：2026-08-07</span></span>
<span class="line"><span>场景：售后执行 Agent（含退款审批）；可升级知识库检索</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题：</span></span>
<span class="line"><span>  需要可交付的全栈边界：流式 Chat、租户鉴权、工具调用、可中断审批。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>硬约束：</span></span>
<span class="line"><span>  TypeScript；密钥服务端；Postgres；自托管 Checkpoint；产品 SSE 协议可控。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>标准（摘要）：</span></span>
<span class="line"><span>  抽象匹配 25 / 恢复 20 / 协议 15 / 测试观测 15 / 学习 10 / 退出 15</span></span>
<span class="line"><span></span></span>
<span class="line"><span>候选：</span></span>
<span class="line"><span>  前端 F1 Nuxt / F2 Next / F3 Vite SPA</span></span>
<span class="line"><span>  后端 B1 Nest / B2 轻量 / B3 Serverless</span></span>
<span class="line"><span>  编排 O1 SDK / O2 LC / O3 LC+LG / O4 托管</span></span>
<span class="line"><span></span></span>
<span class="line"><span>证据（PoC）：</span></span>
<span class="line"><span>  1) Nest SSE + 取消 Run</span></span>
<span class="line"><span>  2) createAgent 查工单 Tool</span></span>
<span class="line"><span>  3) LangGraph interrupt 退款审批并进程重启 resume</span></span>
<span class="line"><span>  4) Model Gateway 别名切换备用 baseURL</span></span>
<span class="line"><span>  5) Nuxt 仅依赖产品事件重建 UI</span></span>
<span class="line"><span></span></span>
<span class="line"><span>决策：</span></span>
<span class="line"><span>  F1 + B1 + O3；模型经 Gateway。</span></span>
<span class="line"><span>  知识库升级默认不强制新图；检索 ACL 在 Nest。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>否决：</span></span>
<span class="line"><span>  浏览器直连模型；无适配的纯托管编排；工作台阶段 Supervisor 多 Agent 网。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后果：</span></span>
<span class="line"><span>  + 与手册模块对齐，可按项目实战验收</span></span>
<span class="line"><span>  − 需维护事件适配与框架升级契约测试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>缓解：</span></span>
<span class="line"><span>  contracts/ 生成类型；CI 跑协议与图恢复测试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>复查：</span></span>
<span class="line"><span>  见正文 §7；审批若迁外部 BPM 则降级 O3→O2 并新开 ADR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关联：</span></span>
<span class="line"><span>  framework-boundaries.md</span></span>
<span class="line"><span>  model-gateway.md（Accepted）</span></span>
<span class="line"><span>  agent-chain-workflow-boundaries.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br></div></div><h3 id="_8-3-填写完成-知识库偏置-变体" tabindex="-1">8.3 填写完成：知识库偏置（变体） <a class="header-anchor" href="#_8-3-填写完成-知识库偏置-变体" aria-label="Permalink to &quot;8.3 填写完成：知识库偏置（变体）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题：知识库助手编排层采用 LangChain.js，LangGraph 可选</span></span>
<span class="line"><span>状态：Accepted</span></span>
<span class="line"><span>日期：2026-08-07</span></span>
<span class="line"><span>决策：前端/后端同售后 ADR；编排选 O2。</span></span>
<span class="line"><span>触发升级到 O3：出现跨天人工审核索引或多阶段失败可恢复 DAG。</span></span>
<span class="line"><span>否决：为「将来可能审批」预先引入 LG。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_8-4-坏-adr-对照" tabindex="-1">8.4 坏 ADR 对照 <a class="header-anchor" href="#_8-4-坏-adr-对照" aria-label="Permalink to &quot;8.4 坏 ADR 对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>坏例子</th><th>问题</th></tr></thead><tbody><tr><td>「我们决定用 LangGraph，因为业界流行」</td><td>无约束、无否决、无复查</td></tr><tr><td>只贴框架 logo 墙</td><td>未拆层，无法单层替换</td></tr><tr><td>候选只有赢家一个</td><td>没有比较就不是决策</td></tr><tr><td>后果只写优点</td><td>审查者无法评估风险</td></tr></tbody></table><h2 id="_9-proof-of-concept-最低证据" tabindex="-1">9. Proof of Concept 最低证据 <a class="header-anchor" href="#_9-proof-of-concept-最低证据" aria-label="Permalink to &quot;9. Proof of Concept 最低证据&quot;">​</a></h2><p>选型 ADR 至少附这 6 类证据之一组（售后）：</p><ol><li>流式 token + 工具事件到 UI</li><li>鉴权失败与租户隔离各一例</li><li>Run 取消实际 abort 下游</li><li>审批 Interrupt + 进程重启 resume</li><li>换 Gateway 备用模型别名不改 Nuxt</li><li>故意让主模型超时，观察失败/回退是否可追踪</li></ol><p>知识库把第 4 条换成：无权限文档不可被引用；索引失败可重试且 UI 状态可校准。</p><h2 id="_10-常见误区" tabindex="-1">10. 常见误区 <a class="header-anchor" href="#_10-常见误区" aria-label="Permalink to &quot;10. 常见误区&quot;">​</a></h2><ol><li><strong>一份 ADR 塞进数据库、CSS、云厂商全部选择</strong>：拆开，引用关联。</li><li><strong>把教程完成度当选型证据</strong>：Hello World 不能证明恢复与取消。</li><li><strong>忽略否决项</strong>：后来者不知道「为什么没选 Serverless」。</li><li><strong>框架边界文与选型文重复抄 API</strong>：边界文讲依赖；本文讲取舍。</li><li><strong>Accepted 后从不复查</strong>：条件清单就是为了允许合法推翻。</li></ol><p>选型是给未来的自己留可执行的退路：层可替换、后果写清、复查有触发器。写完本篇，用 <a href="/ts-ai/architecture/assembly/assembly-recipes-checklist">组装配方与自检</a> 勾选是否具备进入项目实战的决策集。</p><h2 id="_11-与本分组其它文的衔接" tabindex="-1">11. 与本分组其它文的衔接 <a class="header-anchor" href="#_11-与本分组其它文的衔接" aria-label="Permalink to &quot;11. 与本分组其它文的衔接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策问题</th><th>本文</th><th>其它文</th></tr></thead><tbody><tr><td>系统分几层</td><td>点到选型需要拆层</td><td><a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">全栈分层</a></td></tr><tr><td>四框架谁依赖谁</td><td>决策组合</td><td><a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a></td></tr><tr><td>状态放哪</td><td>不展开</td><td><a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">状态所有权</a></td></tr><tr><td>要不要 Gateway</td><td>默认采纳并引用</td><td><a href="/ts-ai/architecture/design-decisions/model-gateway">模型网关</a></td></tr><tr><td>Chain/Agent/Graph 何时用</td><td>编排候选里点到</td><td><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">机制边界</a></td></tr></tbody></table><p>读完决策组后，按目标进入 <a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a>：先完成必修基线，后续升级项目规划中。</p>`,72)])])}const u=a(r,[["render",d]]);export{b as __pageData,u as default};
